"use client";

import React, { useState, useEffect, useCallback } from "react";
import {
  Layers, ShieldAlert, CheckCircle2, AlertTriangle, XCircle, ArrowRight,
  RotateCcw, Download, Play, RefreshCw, Loader2, Sparkles, Filter, FileText,
  Users, Key, Zap, Ban, Check, UserCheck, ShieldCheck, Database, FileSpreadsheet, Lock
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface BulkOperationsPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast?: (message: string, type?: "success" | "error" | "info") => void;
}

type OperationType =
  | "BULK_PLAN_CHANGE"
  | "BULK_ENTITLEMENT_GRANT"
  | "BULK_ENTITLEMENT_REVOKE"
  | "BULK_SUSPEND"
  | "BULK_UNSUSPEND"
  | "BULK_QUOTA_RESET"
  | "BULK_COUPON_GENERATION"
  | "BULK_EXPORT";

export function BulkOperationsPanel({ api, getAuthHeaders, triggerToast }: BulkOperationsPanelProps) {
  // Step State
  const [currentStep, setCurrentStep] = useState<1 | 2 | 3 | 4>(1);

  // Operation State
  const [operationType, setOperationType] = useState<OperationType>("BULK_PLAN_CHANGE");
  const [targetMode, setTargetMode] = useState<"preset" | "manual" | "csv">("preset");
  const [filterPreset, setFilterPreset] = useState<"all" | "free" | "paid" | "blocked">("all");
  const [manualTargets, setManualTargets] = useState("");
  const [csvText, setCsvText] = useState("");

  // Parameter State
  const [planType, setPlanType] = useState("safar_pro_30d");
  const [durationDays, setDurationDays] = useState(30);
  const [creditsDelta, setCreditsDelta] = useState(50);
  const [aiSplitSearchesDelta, setAiSplitSearchesDelta] = useState(10);
  const [splitAccessDays, setSplitAccessDays] = useState(7);
  const [revokeSplitAccess, setRevokeSplitAccess] = useState(true);
  const [suspendReason, setSuspendReason] = useState("Administrative policy violation");

  // Coupon Generation State
  const [couponQty, setCouponQty] = useState(10);
  const [couponPrefix, setCouponPrefix] = useState("TRAYAGO");
  const [couponPlan, setCouponPlan] = useState("safar_pro_7d");
  const [couponMaxRedemptions, setCouponMaxRedemptions] = useState(1);
  const [couponCampaign, setCouponCampaign] = useState("SUMMER2026");
  const [couponUnlimitedSearch, setCouponUnlimitedSearch] = useState(true);
  const [couponUnlimitedPnr, setCouponUnlimitedPnr] = useState(true);
  const [couponUnlimitedLive, setCouponUnlimitedLive] = useState(true);
  const [couponUnlimitedSplit, setCouponUnlimitedSplit] = useState(true);

  // Preview & Job State
  const [previewData, setPreviewData] = useState<any>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [confirmInput, setConfirmInput] = useState("");
  const [activeJob, setActiveJob] = useState<any>(null);
  const [executing, setExecuting] = useState(false);
  const [jobHistory, setJobHistory] = useState<any[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [rollbackLoading, setRollbackLoading] = useState<string | null>(null);

  const toast = useCallback((msg: string, type: "success" | "error" | "info" = "info") => {
    if (triggerToast) triggerToast(msg, type);
    else alert(msg);
  }, [triggerToast]);

  // Load Job History
  const fetchJobHistory = useCallback(async () => {
    try {
      setHistoryLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/bulk/jobs?limit=20`, {
        headers: getAuthHeaders() as any
      });
      const json = await res.json();
      if (json.success) {
        setJobHistory(json.data || []);
      }
    } catch (err: any) {
      console.error("Failed to fetch job history", err);
    } finally {
      setHistoryLoading(false);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchJobHistory();
  }, [fetchJobHistory]);

  // Polling for Active Job Progress
  useEffect(() => {
    if (!activeJob || !activeJob.operationId) return;
    if (activeJob.status === "COMPLETED" || activeJob.status === "PARTIALLY_FAILED" || activeJob.status === "FAILED" || activeJob.status === "CANCELLED" || activeJob.status === "ROLLED_BACK") {
      return;
    }

    const interval = setInterval(async () => {
      try {
        const res = await fetchWithAuth(`${api}/api/admin/bulk/jobs/${activeJob.operationId}`, {
          headers: getAuthHeaders() as any
        });
        const json = await res.json();
        if (json.success && json.data) {
          setActiveJob(json.data);
          if (json.data.status === "COMPLETED" || json.data.status === "PARTIALLY_FAILED" || json.data.status === "FAILED" || json.data.status === "CANCELLED") {
            setExecuting(false);
            fetchJobHistory();
          }
        }
      } catch (err) {
        console.error("Error polling job status", err);
      }
    }, 1200);

    return () => clearInterval(interval);
  }, [activeJob, api, getAuthHeaders, fetchJobHistory]);

  // Build target selector payload
  const buildTargetSelector = () => {
    if (operationType === "BULK_COUPON_GENERATION") {
      return {};
    }

    if (targetMode === "preset") {
      if (filterPreset === "all") return { filter: { all: true } };
      if (filterPreset === "free") return { filter: { planType: "free" } };
      if (filterPreset === "paid") return { filter: { planType: "paid" } };
      if (filterPreset === "blocked") return { filter: { isBlocked: true } };
    }

    if (targetMode === "manual") {
      const items = manualTargets.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);
      const userIds = items.filter(s => !s.includes("@"));
      const userEmails = items.filter(s => s.includes("@"));
      return { userIds, userEmails };
    }

    if (targetMode === "csv") {
      return { csvText };
    }

    return { filter: { all: true } };
  };

  // Build operation parameters payload
  const buildParameters = () => {
    switch (operationType) {
      case "BULK_PLAN_CHANGE":
        return { planType, durationDays: planType === "free" ? undefined : durationDays };
      case "BULK_ENTITLEMENT_GRANT":
        return { creditsDelta, aiSplitSearchesDelta, splitAccessDays };
      case "BULK_ENTITLEMENT_REVOKE":
        return { creditsDelta, aiSplitSearchesDelta, revokeSplitAccess };
      case "BULK_SUSPEND":
        return { reason: suspendReason };
      case "BULK_UNSUSPEND":
        return {};
      case "BULK_QUOTA_RESET":
        return {};
      case "BULK_COUPON_GENERATION":
        return {
          couponQuantity: couponQty,
          couponPrefix,
          couponPlanType: couponPlan,
          couponMaxRedemptions,
          couponCampaign,
          couponUnlimitedSearch,
          couponUnlimitedPnr,
          couponUnlimitedLive,
          couponUnlimitedSplit
        };
      case "BULK_EXPORT":
        return {};
      default:
        return {};
    }
  };

  // Handle Step 1 -> Step 2: Generate Preview
  const handleGeneratePreview = async () => {
    try {
      setPreviewLoading(true);
      const selector = buildTargetSelector();
      const parameters = buildParameters();

      const res = await fetchWithAuth(`${api}/api/admin/bulk/preview`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() as any },
        body: JSON.stringify({ operationType, selector, parameters })
      });

      const json = await res.json();
      if (!json.success) {
        toast(json.error || "Failed to generate preview", "error");
        return;
      }

      setPreviewData(json.data);
      setConfirmInput("");
      setCurrentStep(2);
      toast("Preview generated successfully", "success");
    } catch (err: any) {
      toast(err.message || "Failed to contact bulk operations engine", "error");
    } finally {
      setPreviewLoading(false);
    }
  };

  // Handle Step 2 -> Step 3: Execute Job
  const handleExecuteJob = async () => {
    if (!previewData) return;
    if (confirmInput.trim() !== previewData.confirmationCode) {
      toast(`Confirmation code mismatch. Please enter "${previewData.confirmationCode}"`, "error");
      return;
    }

    try {
      setExecuting(true);
      const selector = buildTargetSelector();
      const parameters = buildParameters();

      const res = await fetchWithAuth(`${api}/api/admin/bulk/execute`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() as any },
        body: JSON.stringify({
          previewId: previewData.previewId,
          confirmationCode: confirmInput.trim(),
          selector,
          parameters
        })
      });

      const json = await res.json();
      if (!json.success) {
        toast(json.error || "Execution failed", "error");
        setExecuting(false);
        return;
      }

      setActiveJob(json.data);
      setCurrentStep(3);
      toast("Background job initiated", "success");
    } catch (err: any) {
      toast(err.message || "Failed to initiate execution", "error");
      setExecuting(false);
    }
  };

  // Handle Cancel Running Job
  const handleCancelJob = async (jobId: string) => {
    try {
      const res = await fetchWithAuth(`${api}/api/admin/bulk/jobs/${jobId}/cancel`, {
        method: "POST",
        headers: { ...getAuthHeaders() as any }
      });
      const json = await res.json();
      if (json.success) {
        toast("Cancellation requested", "info");
      } else {
        toast(json.error || "Cancel failed", "error");
      }
    } catch (err: any) {
      toast(err.message || "Failed to cancel", "error");
    }
  };

  // Handle Rollback Job
  const handleRollbackJob = async (jobId: string) => {
    if (!confirm(`Are you sure you want to rollback all mutations applied by operation ${jobId}?`)) {
      return;
    }

    try {
      setRollbackLoading(jobId);
      const res = await fetchWithAuth(`${api}/api/admin/bulk/jobs/${jobId}/rollback`, {
        method: "POST",
        headers: { ...getAuthHeaders() as any }
      });
      const json = await res.json();
      if (json.success) {
        toast(json.message || "Rollback completed", "success");
        fetchJobHistory();
        if (activeJob?.operationId === jobId) {
          setActiveJob((prev: any) => ({ ...prev, status: "ROLLED_BACK", isRolledBack: true }));
        }
      } else {
        toast(json.error || "Rollback failed", "error");
      }
    } catch (err: any) {
      toast(err.message || "Rollback failed", "error");
    } finally {
      setRollbackLoading(null);
    }
  };

  const getProgressPercentage = () => {
    if (!activeJob || !activeJob.targetCount || activeJob.targetCount === 0) return 0;
    return Math.min(100, Math.round((activeJob.processedCount / activeJob.targetCount) * 100));
  };

  return (
    <div className="space-y-6">
      {/* Top Header Card */}
      <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm relative overflow-hidden">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 relative z-10">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <Layers className="text-indigo-600 dark:text-indigo-400" size={22} />
              <h2 className="text-xl font-bold text-main">Safe Bulk Operations Engine</h2>
              <span className="px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider badge-indigo rounded-full">
                Phase 053 • Preview-First
              </span>
            </div>
            <p className="text-xs text-muted max-w-2xl leading-relaxed">
              Auditable, micro-batched mutations with pre-execution validation, side-effect analysis, rollback snapshots, and strict administrator protections.
            </p>
          </div>

          {/* Stepper Navigation */}
          <div className="flex items-center gap-1 bg-surface border border-subtle p-1 rounded-xl text-xs font-semibold">
            <button
              onClick={() => setCurrentStep(1)}
              className={`px-3 py-1.5 rounded-lg transition ${currentStep === 1 ? "bg-primary text-white shadow-sm font-bold" : "text-muted hover:text-main"}`}>
              1. Select &amp; Configure
            </button>
            <button
              onClick={() => previewData && setCurrentStep(2)}
              disabled={!previewData}
              className={`px-3 py-1.5 rounded-lg transition ${currentStep === 2 ? "bg-primary text-white shadow-sm font-bold" : "text-muted hover:text-main disabled:opacity-40"}`}>
              2. Preview &amp; Verify
            </button>
            <button
              onClick={() => activeJob && setCurrentStep(3)}
              disabled={!activeJob}
              className={`px-3 py-1.5 rounded-lg transition ${currentStep === 3 ? "bg-primary text-white shadow-sm font-bold" : "text-muted hover:text-main disabled:opacity-40"}`}>
              3. Execution &amp; Progress
            </button>
          </div>
        </div>
      </div>

      {/* User Deletion Protective Notice */}
      <div className="bg-rose-50 dark:bg-rose-950/20 border border-rose-200 dark:border-rose-800/40 rounded-xl p-4 flex items-center justify-between text-xs text-rose-800 dark:text-rose-300">
        <div className="flex items-center gap-3">
          <Lock className="text-rose-600 dark:text-rose-400 flex-shrink-0" size={18} />
          <div>
            <span className="font-bold uppercase tracking-wide mr-2">Governance Safety Gate:</span>
            Permanent user deletion is <span className="font-bold underline">disabled</span> because soft-delete and restore pipelines are not available. Destructive deletion endpoints are barred.
          </div>
        </div>
        <span className="px-2 py-0.5 badge-danger rounded font-mono text-[10px] uppercase font-bold">
          DELETE_STATUS: NOT_READY
        </span>
      </div>

      {/* ── STEP 1: CONFIGURE & SELECT TARGETS ── */}
      {currentStep === 1 && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Operation Selector */}
          <div className="lg:col-span-1 space-y-3">
            <h3 className="text-xs font-bold text-muted uppercase tracking-wider">Select Operation</h3>
            <div className="space-y-2">
              {[
                { id: "BULK_PLAN_CHANGE", label: "Plan & Tier Change", desc: "Batch upgrade/downgrade subscription tiers", icon: <Sparkles size={16} className="text-amber-500" /> },
                { id: "BULK_ENTITLEMENT_GRANT", label: "Grant Entitlements", desc: "Add credits or special features", icon: <Zap size={16} className="text-emerald-500" /> },
                { id: "BULK_ENTITLEMENT_REVOKE", label: "Revoke Entitlements", desc: "Deduct credits or remove feature access", icon: <Ban size={16} className="text-rose-500" /> },
                { id: "BULK_SUSPEND", label: "Account Suspension", desc: "Temporarily block offending accounts", icon: <ShieldAlert size={16} className="text-rose-500" /> },
                { id: "BULK_UNSUSPEND", label: "Account Unsuspension", desc: "Restore access to suspended accounts", icon: <UserCheck size={16} className="text-emerald-500" /> },
                { id: "BULK_QUOTA_RESET", label: "Daily Quota Reset", desc: "Reset daily usage counters for selected users", icon: <RotateCcw size={16} className="text-blue-500" /> },
                { id: "BULK_COUPON_GENERATION", label: "Generate Promo Codes", desc: "Batch generate promotional redeemable codes", icon: <Key size={16} className="text-purple-500" /> },
                { id: "BULK_EXPORT", label: "Export Filtered Users", desc: "Generate CSV export for selected user cohort", icon: <FileSpreadsheet size={16} className="text-indigo-500" /> },
              ].map((op) => (
                <div
                  key={op.id}
                  onClick={() => setOperationType(op.id as OperationType)}
                  className={`p-3.5 rounded-xl border transition-all cursor-pointer flex items-center justify-between ${
                    operationType === op.id
                      ? "bg-primary/10 border-primary text-main shadow-sm"
                      : "bg-card border-subtle hover:border-strong text-muted hover:text-main"
                  }`}>
                  <div className="flex items-center gap-3">
                    <div className="p-2 rounded-lg bg-surface border border-subtle">{op.icon}</div>
                    <div>
                      <div className="text-xs font-bold text-main">{op.label}</div>
                      <div className="text-[11px] text-muted">{op.desc}</div>
                    </div>
                  </div>
                  {operationType === op.id && <Check size={16} className="text-primary" />}
                </div>
              ))}
            </div>
          </div>

          {/* Target & Parameters Config */}
          <div className="lg:col-span-2 space-y-6">
            {/* Parameters Card */}
            <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm space-y-4">
              <h3 className="text-sm font-bold text-main flex items-center gap-2">
                <Filter size={16} className="text-indigo-600 dark:text-indigo-400" /> Configure Parameters
              </h3>

              {operationType === "BULK_PLAN_CHANGE" && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Target Subscription Plan</label>
                    <select
                      value={planType}
                      onChange={(e) => setPlanType(e.target.value)}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm">
                      <option value="free">Free Tier (free)</option>
                      <option value="safar_pro_30m">Blitz Pro 30 Mins — ₹9 (safar_pro_30m)</option>
                      <option value="safar_pro_1d">AI Pass 1 Day — ₹19 (safar_pro_1d)</option>
                      <option value="safar_pro_7d">AI Pass 7 Days — ₹19 (safar_pro_7d)</option>
                      <option value="safar_pro_30d">Pro Monthly 30 Days — ₹49 (safar_pro_30d)</option>
                      <option value="safar_pro_90d">Pro Yearly 365 Days — ₹399 (safar_pro_90d)</option>
                      <option value="safar_pro">Legacy Safar Pro 30 Days — ₹149 (safar_pro)</option>
                    </select>
                  </div>
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Duration (Days)</label>
                    <input
                      type="number"
                      min={1}
                      value={durationDays}
                      onChange={(e) => setDurationDays(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                </div>
              )}

              {operationType === "BULK_ENTITLEMENT_GRANT" && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Credits to Add</label>
                    <input
                      type="number"
                      min={0}
                      value={creditsDelta}
                      onChange={(e) => setCreditsDelta(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">AI Split Searches</label>
                    <input
                      type="number"
                      min={0}
                      value={aiSplitSearchesDelta}
                      onChange={(e) => setAiSplitSearchesDelta(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Split Access (Days)</label>
                    <input
                      type="number"
                      min={0}
                      value={splitAccessDays}
                      onChange={(e) => setSplitAccessDays(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                </div>
              )}

              {operationType === "BULK_ENTITLEMENT_REVOKE" && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Credits to Deduct</label>
                    <input
                      type="number"
                      min={0}
                      value={creditsDelta}
                      onChange={(e) => setCreditsDelta(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">AI Searches to Clear</label>
                    <input
                      type="number"
                      min={0}
                      value={aiSplitSearchesDelta}
                      onChange={(e) => setAiSplitSearchesDelta(Number(e.target.value))}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                </div>
              )}

              {operationType === "BULK_SUSPEND" && (
                <div>
                  <label className="text-xs text-muted mb-1.5 block font-bold">Suspension Reason</label>
                  <input
                    type="text"
                    value={suspendReason}
                    onChange={(e) => setSuspendReason(e.target.value)}
                    placeholder="e.g., Terms violation / Automated scraping activity"
                    className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                  />
                </div>
              )}

              {operationType === "BULK_COUPON_GENERATION" && (
                <div className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div>
                      <label className="text-xs text-muted mb-1.5 block font-bold">Quantity (Max 500)</label>
                      <input
                        type="number"
                        min={1}
                        max={500}
                        value={couponQty}
                        onChange={(e) => setCouponQty(Number(e.target.value))}
                        className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs text-muted mb-1.5 block font-bold">Code Prefix</label>
                      <input
                        type="text"
                        value={couponPrefix}
                        onChange={(e) => setCouponPrefix(e.target.value.toUpperCase())}
                        className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs text-muted mb-1.5 block font-bold">Max Redemptions / Code</label>
                      <input
                        type="number"
                        min={1}
                        value={couponMaxRedemptions}
                        onChange={(e) => setCouponMaxRedemptions(Number(e.target.value))}
                        className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="text-xs text-muted mb-1.5 block font-bold">Campaign Tag</label>
                      <input
                        type="text"
                        value={couponCampaign}
                        onChange={(e) => setCouponCampaign(e.target.value)}
                        className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm"
                      />
                    </div>
                    <div>
                      <label className="text-xs text-muted mb-1.5 block font-bold">Associated Plan</label>
                      <select
                        value={couponPlan}
                        onChange={(e) => setCouponPlan(e.target.value)}
                        className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm">
                        <option value="safar_pro_30m">Blitz Pro (30 Mins)</option>
                        <option value="safar_pro_1d">AI Pass (1 Day)</option>
                        <option value="safar_pro_7d">AI Pass (7 Days)</option>
                        <option value="safar_pro_30d">Pro Monthly (30 Days)</option>
                        <option value="safar_pro_90d">Pro Yearly (365 Days)</option>
                      </select>
                    </div>
                  </div>
                </div>
              )}

              {operationType === "BULK_QUOTA_RESET" && (
                <div className="p-3 bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-800/30 rounded-xl text-xs text-blue-800 dark:text-blue-300">
                  Resets today&apos;s daily usage for searches, PNR tracking, and live updates back to zero. Quota policy limits remain untouched.
                </div>
              )}
            </div>

            {/* Target Selection Card (when applicable) */}
            {operationType !== "BULK_COUPON_GENERATION" && (
              <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-sm font-bold text-main flex items-center gap-2">
                    <Users size={16} className="text-indigo-600 dark:text-indigo-400" /> Target Selection
                  </h3>
                  <div className="flex gap-1 bg-surface border border-subtle p-1 rounded-lg text-xs">
                    <button
                      onClick={() => setTargetMode("preset")}
                      className={`px-2.5 py-1 rounded transition font-medium ${targetMode === "preset" ? "bg-card text-main font-bold shadow-sm" : "text-muted"}`}>
                      Filters
                    </button>
                    <button
                      onClick={() => setTargetMode("manual")}
                      className={`px-2.5 py-1 rounded transition font-medium ${targetMode === "manual" ? "bg-card text-main font-bold shadow-sm" : "text-muted"}`}>
                      Manual List
                    </button>
                    <button
                      onClick={() => setTargetMode("csv")}
                      className={`px-2.5 py-1 rounded transition font-medium ${targetMode === "csv" ? "bg-card text-main font-bold shadow-sm" : "text-muted"}`}>
                      CSV Input
                    </button>
                  </div>
                </div>

                {targetMode === "preset" && (
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">Filter Target Scope</label>
                    <select
                      value={filterPreset}
                      onChange={(e) => setFilterPreset(e.target.value as any)}
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs text-main focus:outline-none focus:border-strong shadow-sm">
                      <option value="all">All Non-Admin Users</option>
                      <option value="free">Free Tier Users Only</option>
                      <option value="paid">Subscribed / Paid Users Only</option>
                      <option value="blocked">Currently Suspended / Blocked Users</option>
                    </select>
                  </div>
                )}

                {targetMode === "manual" && (
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">
                      Enter User IDs or Emails (one per line or comma separated)
                    </label>
                    <textarea
                      rows={4}
                      value={manualTargets}
                      onChange={(e) => setManualTargets(e.target.value)}
                      placeholder="user1@example.com&#10;user2@example.com&#10;8f281293-1b91-4c11-9a74-2c70014a958b"
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs font-mono text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                )}

                {targetMode === "csv" && (
                  <div>
                    <label className="text-xs text-muted mb-1.5 block font-bold">
                      Paste CSV Content (with ID or Email column)
                    </label>
                    <textarea
                      rows={4}
                      value={csvText}
                      onChange={(e) => setCsvText(e.target.value)}
                      placeholder="id,email&#10;8f281293-1b91-4c11-9a74-2c70014a958b,user@trayago.in"
                      className="w-full bg-surface border border-subtle rounded-xl px-3.5 py-2.5 text-xs font-mono text-main focus:outline-none focus:border-strong shadow-sm"
                    />
                  </div>
                )}
              </div>
            )}

            {/* Action Bar */}
            <div className="flex justify-end gap-3 pt-2">
              <button
                onClick={handleGeneratePreview}
                disabled={previewLoading}
                className="px-6 py-2.5 bg-primary hover:opacity-90 text-white rounded-xl text-xs font-bold transition-all shadow-sm flex items-center gap-2">
                {previewLoading ? <Loader2 size={16} className="animate-spin" /> : <Play size={16} />}
                Generate Safe Preview
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── STEP 2: PREVIEW & VERIFY ── */}
      {currentStep === 2 && previewData && (
        <div className="space-y-6 text-main">
          <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm space-y-5">
            <div className="flex justify-between items-center border-b border-subtle pb-4">
              <div>
                <h3 className="text-base font-bold text-main flex items-center gap-2">
                  <ShieldCheck size={18} className="text-emerald-600 dark:text-emerald-400" /> Pre-Execution Verification &amp; Impact Analysis
                </h3>
                <p className="text-xs text-muted">Review calculated affected counts, side-effect warnings, and sample mutations before confirming.</p>
              </div>
              <button
                onClick={() => setCurrentStep(1)}
                className="text-xs font-bold text-muted hover:text-main underline">
                Edit Parameters
              </button>
            </div>

            {/* Count Metrics Grid */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="p-4 bg-surface border border-subtle rounded-xl text-center shadow-sm">
                <div className="text-xl font-black text-main font-mono">{previewData.targetCount}</div>
                <div className="text-[11px] text-muted uppercase font-bold mt-1">Total Targets</div>
              </div>
              <div className="p-4 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-200 dark:border-emerald-800/30 rounded-xl text-center shadow-sm">
                <div className="text-xl font-black text-emerald-600 dark:text-emerald-400 font-mono">{previewData.validCount}</div>
                <div className="text-[11px] text-emerald-800 dark:text-emerald-300/80 uppercase font-bold mt-1">Valid for Mutation</div>
              </div>
              <div className="p-4 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800/30 rounded-xl text-center shadow-sm">
                <div className="text-xl font-black text-amber-600 dark:text-amber-400 font-mono">{previewData.skippedCount}</div>
                <div className="text-[11px] text-amber-800 dark:text-amber-300/80 uppercase font-bold mt-1">Skipped / Protected</div>
              </div>
              <div className="p-4 bg-indigo-50 dark:bg-indigo-950/20 border border-indigo-200 dark:border-indigo-800/30 rounded-xl text-center shadow-sm">
                <div className="text-xl font-black text-indigo-600 dark:text-indigo-400 font-mono">~{(previewData.estimatedDurationMs / 1000).toFixed(1)}s</div>
                <div className="text-[11px] text-indigo-800 dark:text-indigo-300/80 uppercase font-bold mt-1">Est. Duration</div>
              </div>
            </div>

            {/* Side Effect Warnings */}
            {previewData.warnings && previewData.warnings.length > 0 && (
              <div className="space-y-2">
                <h4 className="text-xs font-bold text-muted uppercase tracking-wider">Side Effects &amp; Operational Warnings</h4>
                <div className="space-y-1.5">
                  {previewData.warnings.map((w: string, idx: number) => (
                    <div key={idx} className="p-3 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800/30 rounded-xl text-xs text-amber-900 dark:text-amber-300 flex items-center gap-2">
                      <AlertTriangle size={15} className="text-amber-500 shrink-0" />
                      <span>{w}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Sample Records Diff Table */}
            {previewData.sampleDiffs && previewData.sampleDiffs.length > 0 && (
              <div className="space-y-2">
                <h4 className="text-xs font-bold text-muted uppercase tracking-wider">Sample Record State Diffs</h4>
                <div className="border border-subtle rounded-xl overflow-hidden shadow-sm">
                  <table className="w-full text-xs text-left">
                    <thead className="bg-surface text-muted font-bold border-b border-subtle">
                      <tr>
                        <th className="p-3">User Target</th>
                        <th className="p-3">Before State</th>
                        <th className="p-3">After State</th>
                        <th className="p-3">Mutation Summary</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-subtle">
                      {previewData.sampleDiffs.map((d: any, i: number) => (
                        <tr key={i} className="hover:bg-surface/50">
                          <td className="p-3 font-mono text-main font-bold">{d.email || d.userId}</td>
                          <td className="p-3 font-mono text-muted">{JSON.stringify(d.before)}</td>
                          <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400 font-bold">{JSON.stringify(d.after)}</td>
                          <td className="p-3 text-secondary font-medium">{d.changeSummary}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Explicit Confirmation Gate */}
            <div className="p-4 bg-indigo-50 dark:bg-indigo-950/20 border border-indigo-200 dark:border-indigo-800/40 rounded-xl space-y-3">
              <div className="text-xs text-indigo-900 dark:text-indigo-300">
                To confirm and launch this background operation on <span className="font-bold text-main">{previewData.validCount}</span> accounts, type the authorization code below:
              </div>
              <div className="flex flex-col sm:flex-row gap-3 items-center">
                <div className="px-3 py-2 bg-surface border border-subtle rounded-lg font-mono text-xs text-indigo-700 dark:text-indigo-300 font-bold select-all shadow-sm">
                  {previewData.confirmationCode}
                </div>
                <input
                  type="text"
                  value={confirmInput}
                  onChange={(e) => setConfirmInput(e.target.value)}
                  placeholder="Type confirmation code"
                  className="flex-1 bg-surface border border-subtle rounded-lg px-3 py-2 text-xs font-mono text-main focus:outline-none focus:border-strong shadow-sm"
                />
                <button
                  onClick={handleExecuteJob}
                  disabled={executing || confirmInput.trim() !== previewData.confirmationCode}
                  className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-40 text-white rounded-lg text-xs font-bold transition flex items-center gap-2 shadow-sm">
                  {executing && <Loader2 size={14} className="animate-spin" />} Confirm &amp; Launch
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── STEP 3: EXECUTION & PROGRESS ── */}
      {currentStep === 3 && activeJob && (
        <div className="space-y-6 text-main">
          <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm space-y-6">
            <div className="flex justify-between items-center border-b border-subtle pb-4">
              <div>
                <div className="flex items-center gap-2">
                  <h3 className="text-base font-bold text-main">Job Status: {activeJob.operationId}</h3>
                  <span className={`px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full ${
                    activeJob.status === "COMPLETED" ? "badge-success" :
                    activeJob.status === "RUNNING" ? "badge-info animate-pulse" :
                    activeJob.status === "PARTIALLY_FAILED" ? "badge-warning" :
                    activeJob.status === "CANCELLED" ? "badge-neutral" :
                    activeJob.status === "ROLLED_BACK" ? "badge-purple" :
                    "badge-danger"
                  }`}>
                    {activeJob.status}
                  </span>
                </div>
                <p className="text-xs text-muted">Type: {activeJob.operationType} • Admin: {activeJob.adminEmail}</p>
              </div>

              {activeJob.status === "RUNNING" && (
                <button
                  onClick={() => handleCancelJob(activeJob.operationId)}
                  className="px-3 py-1.5 badge-danger rounded-lg text-xs font-bold transition shadow-sm">
                  Cancel Execution
                </button>
              )}
            </div>

            {/* Progress Bar */}
            <div className="space-y-2">
              <div className="flex justify-between text-xs font-mono">
                <span className="text-muted">Processed: {activeJob.processedCount} / {activeJob.targetCount}</span>
                <span className="text-indigo-600 dark:text-indigo-400 font-bold">{getProgressPercentage()}%</span>
              </div>
              <div className="w-full h-3 bg-surface rounded-full overflow-hidden border border-subtle">
                <div
                  className="h-full bg-gradient-to-r from-indigo-500 to-emerald-500 transition-all duration-300"
                  style={{ width: `${getProgressPercentage()}%` }}
                />
              </div>
            </div>

            {/* Execution Metrics Grid */}
            <div className="grid grid-cols-3 gap-4">
              <div className="p-4 bg-emerald-50 dark:bg-emerald-950/20 border border-emerald-200 dark:border-emerald-800/30 rounded-xl text-center shadow-sm">
                <div className="text-2xl font-black text-emerald-600 dark:text-emerald-400 font-mono">{activeJob.successCount}</div>
                <div className="text-[11px] text-emerald-800 dark:text-emerald-300/80 uppercase font-bold mt-1">Successful</div>
              </div>
              <div className="p-4 bg-rose-50 dark:bg-rose-950/20 border border-rose-200 dark:border-rose-800/30 rounded-xl text-center shadow-sm">
                <div className="text-2xl font-black text-rose-600 dark:text-rose-400 font-mono">{activeJob.failureCount}</div>
                <div className="text-[11px] text-rose-800 dark:text-rose-300/80 uppercase font-bold mt-1">Failed</div>
              </div>
              <div className="p-4 bg-indigo-50 dark:bg-indigo-950/20 border border-indigo-200 dark:border-indigo-800/30 rounded-xl text-center shadow-sm">
                <div className="text-2xl font-black text-indigo-600 dark:text-indigo-400 font-mono">{activeJob.skippedCount}</div>
                <div className="text-[11px] text-indigo-800 dark:text-indigo-300/80 uppercase font-bold mt-1">Skipped</div>
              </div>
            </div>

            {/* Action buttons (Download export / Rollback) */}
            <div className="flex flex-wrap gap-3 pt-2">
              {activeJob.hasExportData && (
                <a
                  href={`${api}/api/admin/bulk/jobs/${activeJob.operationId}/export`}
                  download
                  className="px-4 py-2 bg-primary hover:opacity-90 text-white rounded-xl text-xs font-bold transition flex items-center gap-2 shadow-sm">
                  <Download size={14} /> Download Exported CSV
                </a>
              )}

              {activeJob.isRollbackCapable && !activeJob.isRolledBack && (activeJob.status === "COMPLETED" || activeJob.status === "PARTIALLY_FAILED") && (
                <button
                  onClick={() => handleRollbackJob(activeJob.operationId)}
                  disabled={!!rollbackLoading}
                  className="px-4 py-2 bg-amber-500 hover:bg-amber-400 text-black rounded-xl text-xs font-bold transition flex items-center gap-2 shadow-sm">
                  {rollbackLoading === activeJob.operationId ? <Loader2 size={14} className="animate-spin" /> : <RotateCcw size={14} />}
                  Rollback All Mutations
                </button>
              )}

              <button
                onClick={() => { setCurrentStep(1); setPreviewData(null); }}
                className="px-4 py-2 bg-surface hover:bg-card border border-subtle text-main rounded-xl text-xs font-bold transition shadow-sm">
                Start New Operation
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── JOB HISTORY SECTION ── */}
      <div className="bg-card border border-subtle rounded-2xl p-6 shadow-sm space-y-4 text-main">
        <div className="flex justify-between items-center">
          <h3 className="text-sm font-bold text-main flex items-center gap-2">
            <RotateCcw size={16} className="text-indigo-600 dark:text-indigo-400" /> Historical Bulk Operations &amp; Audits
          </h3>
          <button
            onClick={fetchJobHistory}
            disabled={historyLoading}
            className="p-1.5 bg-surface border border-subtle hover:bg-card rounded-lg text-muted hover:text-main transition shadow-sm">
            <RefreshCw size={14} className={historyLoading ? "animate-spin" : ""} />
          </button>
        </div>

        {jobHistory.length === 0 ? (
          <div className="p-8 text-center text-xs text-muted">No bulk operations recorded in history yet.</div>
        ) : (
          <div className="border border-subtle rounded-xl overflow-hidden shadow-sm">
            <table className="w-full text-xs text-left">
              <thead className="bg-surface text-muted font-bold border-b border-subtle">
                <tr>
                  <th className="p-3">Operation ID</th>
                  <th className="p-3">Type</th>
                  <th className="p-3">Status</th>
                  <th className="p-3">Target Count</th>
                  <th className="p-3">Success / Fail</th>
                  <th className="p-3">Admin</th>
                  <th className="p-3">Timestamp</th>
                  <th className="p-3 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-subtle">
                {jobHistory.map((j) => (
                  <tr key={j.operationId} className="hover:bg-surface/50">
                    <td className="p-3 font-mono font-bold text-main">{j.operationId}</td>
                    <td className="p-3 text-secondary font-medium">{j.operationType}</td>
                    <td className="p-3">
                      <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full ${
                        j.status === "COMPLETED" ? "badge-success" :
                        j.status === "RUNNING" ? "badge-info" :
                        j.status === "PARTIALLY_FAILED" ? "badge-warning" :
                        j.status === "ROLLED_BACK" ? "badge-purple" :
                        "badge-danger"
                      }`}>
                        {j.status}
                      </span>
                    </td>
                    <td className="p-3 font-mono text-main">{j.targetCount}</td>
                    <td className="p-3 font-mono text-emerald-600 dark:text-emerald-400 font-bold">
                      {j.successCount} <span className="text-muted">/</span> <span className="text-rose-600 dark:text-rose-400">{j.failureCount}</span>
                    </td>
                    <td className="p-3 text-muted">{j.adminEmail}</td>
                    <td className="p-3 text-muted">{new Date(j.createdAt).toLocaleString()}</td>
                    <td className="p-3 text-right">
                      <div className="flex justify-end gap-2">
                        {j.isRollbackCapable && !j.isRolledBack && (j.status === "COMPLETED" || j.status === "PARTIALLY_FAILED") && (
                          <button
                            onClick={() => handleRollbackJob(j.operationId)}
                            disabled={rollbackLoading === j.operationId}
                            className="px-2 py-1 bg-amber-100 dark:bg-amber-950/30 border border-amber-300 dark:border-amber-800/30 text-amber-800 dark:text-amber-400 hover:bg-amber-200 rounded text-[10px] font-bold transition flex items-center gap-1">
                            {rollbackLoading === j.operationId ? <Loader2 size={10} className="animate-spin" /> : <RotateCcw size={10} />}
                            Rollback
                          </button>
                        )}
                        <a
                          href={`${api}/api/admin/bulk/jobs/${j.operationId}/export`}
                          download
                          className="px-2 py-1 bg-surface hover:bg-card border border-subtle rounded text-[10px] font-bold text-secondary hover:text-main transition flex items-center gap-1 shadow-sm">
                          <Download size={10} /> CSV
                        </a>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
