"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  X, User, Mail, Phone, Calendar, Zap, Gift, 
  Send, Search, Banknote, Bell, Loader2, CheckCircle2, ArrowRight
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface User360DrawerProps {
  userId: string | null;
  api: string;
  getAuthHeaders: () => Record<string, string>;
  onClose: () => void;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
  onRefreshUsers?: () => void;
}

export function User360Drawer({
  userId,
  api,
  getAuthHeaders,
  onClose,
  triggerToast,
  onRefreshUsers
}: User360DrawerProps) {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [activeTab, setActiveTab] = useState<"searches" | "payments" | "notifications">("searches");
  const [gifting, setGifting] = useState<string | null>(null);
  
  // Custom message form state
  const [showMsgForm, setShowMsgForm] = useState<boolean>(false);
  const [msgTitle, setMsgTitle] = useState<string>("");
  const [msgBody, setMsgBody] = useState<string>("");
  const [sendingMsg, setSendingMsg] = useState<boolean>(false);

  const fetchUser360 = useCallback(async () => {
    if (!userId) return;
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/users/${userId}/360`, {
        headers: getAuthHeaders()
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setData(json.data);
        }
      }
    } catch {
      triggerToast("Failed to fetch User 360 profile", "error");
    } finally {
      setLoading(false);
    }
  }, [userId, api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchUser360();
  }, [fetchUser360]);

  const handleGiftPerk = async (perkType: "PRO_PASS_7D" | "FREE_SEARCHES_5") => {
    if (!userId) return;
    try {
      setGifting(perkType);
      const res = await fetchWithAuth(`${api}/api/admin/users/${userId}/gift-perk`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ perkType })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast(json.message || "Perk granted successfully!", "success");
        fetchUser360();
        if (onRefreshUsers) onRefreshUsers();
      } else {
        triggerToast(json.error || "Failed to grant perk", "error");
      }
    } catch {
      triggerToast("Network error while granting perk", "error");
    } finally {
      setGifting(null);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId || !msgTitle.trim() || !msgBody.trim()) return;

    try {
      setSendingMsg(true);
      const res = await fetchWithAuth(`${api}/api/admin/users/${userId}/send-message`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({ title: msgTitle, message: msgBody })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast("In-app notification dispatched to user!", "success");
        setMsgTitle("");
        setMsgBody("");
        setShowMsgForm(false);
        fetchUser360();
      } else {
        triggerToast(json.error || "Failed to send message", "error");
      }
    } catch {
      triggerToast("Failed to send message", "error");
    } finally {
      setSendingMsg(false);
    }
  };

  if (!userId) return null;

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="w-full max-w-xl bg-card border-l border-subtle h-full flex flex-col shadow-2xl animate-in slide-in-from-right duration-300 overflow-hidden text-main">
        {/* Top Header */}
        <div className="p-5 border-b border-subtle flex items-center justify-between bg-surface/50">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center text-primary font-bold text-base">
              {data?.user?.name ? data.user.name.charAt(0).toUpperCase() : "U"}
            </div>
            <div>
              <h3 className="font-bold text-main text-base flex items-center gap-2">
                <span>{data?.user?.name || "Passenger Profile"}</span>
                {data?.user?.isAdmin && (
                  <span className="px-2 py-0.5 rounded-full bg-rose-500/15 text-rose-500 text-[10px] font-bold">ADMIN</span>
                )}
              </h3>
              <p className="text-xs text-muted font-mono">{data?.user?.email || userId}</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl bg-surface hover:bg-input border border-subtle text-muted hover:text-main transition"
          >
            <X size={16} />
          </button>
        </div>

        {loading ? (
          <div className="flex-1 flex items-center justify-center gap-2 text-muted text-xs">
            <Loader2 size={20} className="animate-spin text-primary" />
            <span>Loading 360° Passenger Profile...</span>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-5 space-y-5">
            {/* User Overview Stats Grid */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 bg-surface p-4 rounded-2xl border border-subtle">
              <div>
                <span className="text-[10px] text-muted uppercase font-bold">Plan Type</span>
                <div className="text-xs font-bold text-main mt-0.5 capitalize">{data?.user?.planType || "Free"}</div>
              </div>
              <div>
                <span className="text-[10px] text-muted uppercase font-bold">Joined</span>
                <div className="text-xs font-semibold text-main mt-0.5">
                  {data?.user?.createdAt ? new Date(data.user.createdAt).toLocaleDateString("en-IN") : "—"}
                </div>
              </div>
              <div>
                <span className="text-[10px] text-muted uppercase font-bold">Daily Searches</span>
                <div className="text-xs font-bold text-indigo-400 mt-0.5 font-mono">
                  {data?.user?.dailySearchCount ?? 0}
                </div>
              </div>
              <div>
                <span className="text-[10px] text-muted uppercase font-bold">Mobile</span>
                <div className="text-xs font-mono text-muted mt-0.5">{data?.user?.phone || "—"}</div>
              </div>
            </div>

            {/* Quick Actions / Customer Delight */}
            <div className="space-y-2">
              <span className="text-[11px] font-bold text-muted uppercase tracking-wider">
                Direct Customer Delight &amp; Engagement
              </span>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
                <button
                  onClick={() => handleGiftPerk("PRO_PASS_7D")}
                  disabled={!!gifting}
                  className="p-3 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 text-xs font-bold transition flex items-center justify-center gap-1.5 shadow-sm disabled:opacity-50"
                >
                  <Gift size={14} />
                  <span>{gifting === "PRO_PASS_7D" ? "Granting..." : "Gift 7D Pro"}</span>
                </button>

                <button
                  onClick={() => handleGiftPerk("FREE_SEARCHES_5")}
                  disabled={!!gifting}
                  className="p-3 rounded-xl bg-indigo-500/10 hover:bg-indigo-500/20 border border-indigo-500/30 text-indigo-500 text-xs font-bold transition flex items-center justify-center gap-1.5 shadow-sm disabled:opacity-50"
                >
                  <Zap size={14} />
                  <span>{gifting === "FREE_SEARCHES_5" ? "Adding..." : "+5 Searches"}</span>
                </button>

                <button
                  onClick={() => setShowMsgForm(!showMsgForm)}
                  className="p-3 rounded-xl bg-surface hover:bg-input border border-subtle text-main text-xs font-bold transition flex items-center justify-center gap-1.5 shadow-sm"
                >
                  <Send size={14} className="text-primary" />
                  <span>Send Message</span>
                </button>
              </div>
            </div>

            {/* Direct Message Compose Form */}
            {showMsgForm && (
              <form onSubmit={handleSendMessage} className="p-4 rounded-2xl bg-surface border border-primary/30 space-y-3 animate-in fade-in">
                <div className="text-xs font-bold text-main flex items-center gap-1.5">
                  <Send size={13} className="text-primary" /> Send In-App Notification / Alert
                </div>
                <input
                  type="text"
                  placeholder="Notification title..."
                  value={msgTitle}
                  onChange={(e) => setMsgTitle(e.target.value)}
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-1.5 text-xs text-main focus:outline-none focus:border-strong transition"
                />
                <textarea
                  rows={2}
                  placeholder="Write message to passenger..."
                  value={msgBody}
                  onChange={(e) => setMsgBody(e.target.value)}
                  className="w-full bg-input border border-subtle rounded-xl px-3 py-1.5 text-xs text-main focus:outline-none focus:border-strong transition resize-none"
                />
                <div className="flex justify-end gap-2">
                  <button
                    type="button"
                    onClick={() => setShowMsgForm(false)}
                    className="px-3 py-1 text-xs text-muted hover:text-main"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={sendingMsg || !msgTitle.trim() || !msgBody.trim()}
                    className="px-4 py-1.5 bg-primary text-white rounded-xl text-xs font-bold shadow disabled:opacity-50"
                  >
                    {sendingMsg ? "Sending..." : "Send Alert"}
                  </button>
                </div>
              </form>
            )}

            {/* Activity History Tabs */}
            <div className="space-y-3">
              <div className="flex items-center gap-1 bg-surface p-1 rounded-xl border border-subtle">
                <button
                  onClick={() => setActiveTab("searches")}
                  className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition ${
                    activeTab === "searches" ? "bg-card text-main shadow border border-subtle" : "text-muted hover:text-main"
                  }`}
                >
                  Searches ({data?.searches?.length || 0})
                </button>
                <button
                  onClick={() => setActiveTab("payments")}
                  className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition ${
                    activeTab === "payments" ? "bg-card text-main shadow border border-subtle" : "text-muted hover:text-main"
                  }`}
                >
                  Payments ({data?.transactions?.length || 0})
                </button>
                <button
                  onClick={() => setActiveTab("notifications")}
                  className={`flex-1 py-1.5 text-xs font-bold rounded-lg transition ${
                    activeTab === "notifications" ? "bg-card text-main shadow border border-subtle" : "text-muted hover:text-main"
                  }`}
                >
                  Notifications ({data?.notifications?.length || 0})
                </button>
              </div>

              {/* Tab 1: Searches */}
              {activeTab === "searches" && (
                <div className="space-y-2">
                  {data?.searches?.length > 0 ? (
                    data.searches.map((s: any, idx: number) => (
                      <div key={idx} className="p-3 rounded-xl bg-surface border border-subtle flex items-center justify-between text-xs">
                        <div>
                          <div className="font-bold text-main flex items-center gap-1.5">
                            <span>{s.source}</span>
                            <ArrowRight size={11} className="text-muted" />
                            <span>{s.destination}</span>
                          </div>
                          <div className="text-[10px] text-muted mt-0.5">
                            Date: {s.date || "Anytime"} &bull; Direct Trains: {s.direct_train_count ?? 1}
                          </div>
                        </div>
                        <span className="text-[10px] text-muted font-mono">
                          {s.created_at ? new Date(s.created_at).toLocaleDateString("en-IN") : "Recent"}
                        </span>
                      </div>
                    ))
                  ) : (
                    <div className="py-8 text-center text-xs text-muted">No searches recorded for this passenger.</div>
                  )}
                </div>
              )}

              {/* Tab 2: Payments */}
              {activeTab === "payments" && (
                <div className="space-y-2">
                  {data?.transactions?.length > 0 ? (
                    data.transactions.map((tx: any, idx: number) => (
                      <div key={idx} className="p-3 rounded-xl bg-surface border border-subtle flex items-center justify-between text-xs">
                        <div>
                          <div className="font-bold text-main capitalize">{tx.plan_id || "Subscription"}</div>
                          <div className="text-[10px] text-muted font-mono">{tx.provider} &bull; {tx.order_id}</div>
                        </div>
                        <div className="text-right">
                          <div className="font-black font-mono text-emerald-500">₹{tx.amount}</div>
                          <span className="px-1.5 py-0.5 rounded text-[9px] font-bold uppercase bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
                            {tx.status}
                          </span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="py-8 text-center text-xs text-muted">No paid transactions found for this user.</div>
                  )}
                </div>
              )}

              {/* Tab 3: Notifications */}
              {activeTab === "notifications" && (
                <div className="space-y-2">
                  {data?.notifications?.length > 0 ? (
                    data.notifications.map((n: any, idx: number) => (
                      <div key={idx} className="p-3 rounded-xl bg-surface border border-subtle space-y-1 text-xs">
                        <div className="font-bold text-main">{n.title}</div>
                        <p className="text-muted text-[11px]">{n.message}</p>
                        <div className="text-[9px] text-muted font-mono pt-1">
                          {n.created_at ? new Date(n.created_at).toLocaleString("en-IN") : ""}
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="py-8 text-center text-xs text-muted">No notifications sent to this passenger yet.</div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
