/* eslint-disable @typescript-eslint/no-explicit-any */
import React, { useState, useEffect, useCallback } from "react";
import { motion } from "framer-motion";
import {
  Flame, RefreshCw, AlertOctagon, CheckCircle2, ShieldAlert,
  Clock, Hash, FileCode, CheckSquare, Layers
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { API_HOST } from "@/lib/api";

interface ProductionIncidentsPanelProps {
  api?: string;
  getAuthHeaders?: () => any;
}

export function ProductionIncidentsPanel({ api = API_HOST, getAuthHeaders }: ProductionIncidentsPanelProps) {
  const [report, setReport] = useState<any>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [refreshing, setRefreshing] = useState<boolean>(false);

  const fetchIncidents = useCallback(async () => {
    try {
      setRefreshing(true);
      const headers = getAuthHeaders ? getAuthHeaders() : {};
      const res = await fetchWithAuth(`${api}/api/admin/production-incidents`, { headers });
      const json = await res.json();
      if (json.success) {
        setReport(json.data);
      }
    } catch (err) {
      console.error("Failed to fetch Production Incidents report", err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchIncidents();
  }, [fetchIncidents]);

  if (loading) {
    return (
      <div className="p-8 text-center text-muted flex flex-col items-center gap-3">
        <RefreshCw size={24} className="animate-spin text-red-500" />
        <span className="text-sm">Analyzing Production Telemetry Incidents...</span>
      </div>
    );
  }

  const metrics = report?.metrics;

  return (
    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="space-y-6 text-main">
      {/* Top Banner Header */}
      <div className="bg-card border border-subtle rounded-2xl p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 shadow-sm">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Flame size={22} className="text-rose-500 animate-pulse" />
            <h2 className="text-xl font-bold text-main">Production Incident Intelligence</h2>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-mono font-bold badge-neutral">
              {report?.execution_time_ms || 0}ms Latency
            </span>
          </div>
          <p className="text-xs text-muted">
            Automated deduplication, severity classification, root cause analysis, and backlog task synthesis.
          </p>
        </div>
        <button
          onClick={fetchIncidents}
          disabled={refreshing}
          className="flex items-center gap-2 bg-surface hover:bg-card border border-subtle text-main text-xs font-bold px-4 py-2 rounded-xl transition shadow-sm"
        >
          <RefreshCw size={14} className={refreshing ? "animate-spin text-primary" : ""} />
          Refresh Incident Log
        </button>
      </div>

      {/* Incident Severity Summary Bento */}
      <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-3">
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1 shadow-sm">
          <p className="text-[10px] font-bold text-muted uppercase">Total Incidents</p>
          <p className="text-lg font-bold text-main">{metrics?.total_incidents || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1 shadow-sm">
          <p className="text-[10px] font-bold text-muted uppercase">Open</p>
          <p className="text-lg font-bold text-amber-600 dark:text-amber-400">{metrics?.open_incidents || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1 shadow-sm">
          <p className="text-[10px] font-bold text-muted uppercase">Resolved</p>
          <p className="text-lg font-bold text-emerald-600 dark:text-emerald-400">{metrics?.resolved_incidents || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1 shadow-sm">
          <p className="text-[10px] font-bold text-muted uppercase">Critical</p>
          <p className="text-lg font-bold text-rose-600 dark:text-rose-400">{metrics?.critical_count || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1 shadow-sm">
          <p className="text-[10px] font-bold text-muted uppercase">High</p>
          <p className="text-lg font-bold text-orange-600 dark:text-orange-400">{metrics?.high_count || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1">
          <p className="text-[10px] font-bold text-muted uppercase">Medium</p>
          <p className="text-lg font-bold text-yellow-400">{metrics?.medium_count || 0}</p>
        </div>
        <div className="bg-card border border-subtle rounded-xl p-3.5 space-y-1">
          <p className="text-[10px] font-bold text-muted uppercase">Low / Info</p>
          <p className="text-lg font-bold text-blue-400">{(metrics?.low_count || 0) + (metrics?.info_count || 0)}</p>
        </div>
      </div>

      {/* Grid Row: Incidents List & Generated Engineering Backlog */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Deduplicated Telemetry Incidents List */}
        <div className="bg-card border border-subtle rounded-2xl p-5 space-y-4">
          <h3 className="text-base font-bold text-main flex items-center gap-2">
            <AlertOctagon size={18} className="text-red-400" /> Deduplicated Incidents
          </h3>
          <div className="space-y-3">
            {report?.incidents?.map((inc: any, idx: number) => (
              <div key={idx} className="p-4 bg-input border border-red-500/20 rounded-xl space-y-2.5">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] font-bold font-mono px-2 py-0.5 rounded-full ${
                      inc.severity === 'CRITICAL' ? 'bg-red-500/20 text-red-400 border border-red-500/30' :
                      inc.severity === 'HIGH' ? 'bg-orange-500/20 text-orange-400 border border-orange-500/30' :
                      'bg-blue-500/20 text-blue-400 border border-blue-500/30'
                    }`}>
                      {inc.severity}
                    </span>
                    <span className="text-xs font-bold text-main">{inc.title}</span>
                  </div>
                  <span className="text-[10px] font-mono text-muted flex items-center gap-1">
                    <Hash size={10} /> {inc.occurrences} {inc.occurrences === 1 ? 'occurrence' : 'occurrences'}
                  </span>
                </div>

                <div className="bg-card p-2.5 rounded-lg border border-subtle space-y-1">
                  <p className="text-[11px] font-mono text-muted"><strong>Evidence:</strong> {inc.evidence}</p>
                  <p className="text-[11px] text-main"><strong>Likely Root Cause:</strong> {inc.likely_root_cause}</p>
                  <p className="text-[11px] text-green-400"><strong>Suggested Fix:</strong> {inc.suggested_fix}</p>
                </div>

                <div className="flex items-center justify-between text-[10px] text-muted border-t border-subtle pt-2">
                  <span>Module: <strong className="text-main">{inc.affected_module}</strong></span>
                  <span>Confidence: <strong className="text-purple-400">{inc.confidence_score}%</strong></span>
                  <span>Status: <strong className={inc.status === 'RESOLVED' ? 'text-green-400' : 'text-amber-400'}>{inc.status}</strong></span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Generated Engineering Tasks */}
        <div className="bg-card border border-subtle rounded-2xl p-5 space-y-4">
          <h3 className="text-base font-bold text-main flex items-center gap-2">
            <CheckSquare size={18} className="text-purple-400" /> Auto-Generated Engineering Tasks
          </h3>
          <div className="space-y-3">
            {report?.tasks?.length === 0 ? (
              <div className="p-6 text-center text-xs text-muted bg-input rounded-xl border border-subtle">
                No active engineering tasks generated. All operational metrics within target bounds.
              </div>
            ) : (
              report?.tasks?.map((tsk: any, idx: number) => (
                <div key={idx} className="p-3.5 bg-input border border-subtle rounded-xl space-y-2 text-xs">
                  <div className="flex items-center justify-between">
                    <span className="font-bold text-main">{tsk.title}</span>
                    <span className="text-[10px] font-mono font-bold px-2 py-0.5 rounded-full bg-purple-500/10 text-purple-400 border border-purple-500/20">
                      Priority {tsk.priority}
                    </span>
                  </div>
                  <div className="flex items-center justify-between text-[10px] text-muted border-t border-subtle pt-2 mt-1">
                    <span>Category: <strong className="text-main">{tsk.category}</strong></span>
                    <span>Effort: <strong className="text-amber-400">{tsk.estimated_effort}</strong></span>
                    <span>Owner: <strong className="text-main">{tsk.suggested_owner}</strong></span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </motion.div>
  );
}
